// ===== 通用类型判断 =====
function getType(value) {
  // Object.prototype.toString 返回 '[object Xxx]'
  return Object.prototype.toString.call(value).slice(8, -1).toLowerCase();
}

getType(null);        // 'null'
getType([]);          // 'array'
getType({});          // 'object'
getType(new Map());   // 'map'
getType(/\d+/);       // 'regexp'
getType(42n);         // 'bigint'
getType(Symbol('s')); // 'symbol'
getType(new Date());  // 'date'

// ===== 判断普通对象 =====
function isPlainObject(value) {
  if (typeof value !== 'object' || value === null) return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

isPlainObject({});                // true
isPlainObject(Object.create(null)); // true（无原型对象也算普通对象）
isPlainObject([]);                // false
isPlainObject(new Date());        // false
isPlainObject(Object.create({a:1})); // false（原型不是 Object.prototype）

// ===== 隐式类型转换经典面试题 =====
// + 运算符规则：任一操作数是字符串 → 字符串拼接；否则 → 数字相加
console.log([] + []);          // ''（[] → '' + [] → '' = ''）
console.log([] + {});          // '[object Object]'（'' + '[object Object]'）
console.log({} + []);          // 0（语句开头 {} 被解析为空代码块，+ [] → Number([]) → 0）
console.log(true + true);      // 2（true → 1）
console.log('1' + 2 + 3);     // '123'（左结合：'1'+'2' → '12'，'12'+3 → '123'）
console.log(1 + 2 + '3');     // '33'（1+2=3，3+'3' → '33'）

// == 转换规则
console.log(null == undefined);  // true（特殊规则）
console.log(null == 0);          // false（null 只 == undefined）
console.log('' == 0);            // true（'' → 0）
console.log('' == false);        // true（都转数字 → 0）
console.log([] == false);        // true（[] → '' → 0，false → 0）

// Object.is 精确相等
console.log(Object.is(NaN, NaN)); // true  （=== 为 false）
console.log(Object.is(+0, -0));   // false （=== 为 true）
console.log(NaN === NaN);         // false
console.log(+0 === -0);           // true
